<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="with-us" id="<?php echo esc_attr( $root_id ); ?>" aria-labelledby="<?php echo esc_attr( $title_id ); ?>" data-horizontal-slider><div class="container">
  <header class="with-us__header"><h2 id="<?php echo esc_attr( $title_id ); ?>"><?php echo esc_html( $section_data['title'] ?? '' ); ?></h2><div><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div></header>
  <div class="with-us__viewport" data-horizontal-slider-viewport tabindex="0"><div class="with-us__track" data-horizontal-slider-track><?php foreach ( $items as $item ) : ?><article class="with-us__card" data-horizontal-slider-slide><h3><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php echo platejka_section_image( $item['image'] ?? 0, 'medium', array( 'loading' => 'lazy', 'sizes' => '(max-width: 767px) 100vw, 240px' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></article><?php endforeach; ?></div></div>
</div></section>
